/* Organizer history: transforms remain reversible and source geometry remains untouched. */
let undoHistory=[],redoHistory=[],historyGesture=null;
function sameHistory(a,b){return JSON.stringify(a)===JSON.stringify(b)}
function recordHistory(before){const after=snapshot();if(sameHistory(before,after))return;undoHistory.push(before);if(undoHistory.length>80)undoHistory.shift();redoHistory=[]}
function undoOrganizer(){const before=snapshot(),previous=undoHistory.pop();if(!previous)return;redoHistory.push(before);restore(previous)}
function redoOrganizer(){const before=snapshot(),next=redoHistory.pop();if(!next)return;undoHistory.push(before);restore(next)}
svg.addEventListener('pointerdown',event=>{if(event.target.closest('[data-shape]'))historyGesture=snapshot()});svg.addEventListener('pointerup',()=>{if(historyGesture){recordHistory(historyGesture);historyGesture=null}});
['send-back','bring-front','random-location','rotate-left','rotate-right','random-rotate','toggle-layer-visibility'].forEach(id=>{const button=$(id),action=button?.onclick;if(!action)return;button.onclick=event=>{const before=snapshot();action(event);recordHistory(before)}});
document.addEventListener('keydown',event=>{if(!(event.ctrlKey||event.metaKey)||event.key.toLowerCase()!=='z'||event.target.matches('input,textarea,[contenteditable="true"]'))return;event.preventDefault();event.shiftKey?redoOrganizer():undoOrganizer()});
