function selectedBoardItems(){const ids=[...boardSelections].filter(key=>key.startsWith('iteration:')).map(key=>key.slice('iteration:'.length));const p=project();return (ids.length?ids:[activeBoard()?.id]).map(id=>p.iterations.find(board=>board.id===id)).filter(Boolean)}
