/* Type framework template — LOBBY is the first complete spatial scorecard. */
const typeCriterionTemplates={
  LOBBY:{
    title:'LOBBY / 2D CANDIDATE CRITERIA',
    note:'SCORES DESCRIBE LOBBY-GENERATING POTENTIAL, NOT A FINISHED FLOOR PLAN.',
    criteria:[
      ['LP-01','ARRIVAL + FOCAL','No convincing approach or focal field.','A plausible arrival relationship needs more organization.','Clear approaches lead to a dominant relational field.'],
      ['LP-02','BRANCHING DISTRIBUTION','Undifferentiated or arbitrarily fragmented.','One or two branches, but hierarchy is unclear.','Differentiated branches and junctions organize multiple destinations.'],
      ['LP-03','FLOW + DWELL','Movement and occupation are indistinguishable.','Broad and narrow zones exist but roles are unclear.','Connectors, expansions, and pockets support distinct spatial roles.'],
      ['LP-04','THRESHOLD + DEPTH','Uniform or accidentally constricted.','Some variation, but no strong spatial gradient.','Compression, expansion, nesting, and depth form a legible sequence.'],
      ['LP-05','SECTIONAL TRANSLATION','Primarily one flat or uniform zone.','Several regions could take sectional roles.','Branches, cuts, voids, or components suggest levels and vertical relations.']
    ]
  },
  WORKSPACE:{
    title:'WORKSPACE / 2D CANDIDATE CRITERIA',
    note:'SCORES DESCRIBE WORKSPACE-GENERATING POTENTIAL, NOT A FINISHED WORKPLACE.',
    criteria:[
      ['WP-01','PROCESS-FITTED DIFFERENTIATION','Work modes occupy identical, unusable, or disconnected regions.','Several work modes receive distinct regions, but some remain unsupported or inefficiently related.','All tested work modes receive suitable, differentiated, and connected regions.'],
      ['WP-02','FOCUS–EXCHANGE CHOICE','One uniform exposure condition: continuously interrupted or completely isolated.','Focus and exchange zones are plausible, but transitions and choices remain limited.','A clear gradient supports collaboration, ambient awareness, concentration, and withdrawal.'],
      ['WP-03','WORKFLOW + RESOURCES','Related processes and resources are disconnected, indirect, or depend on ambiguous paths.','A usable network is possible, but some workflows or resources remain poorly connected.','A direct, legible network connects required processes and resources.'],
      ['WP-04','RECONFIGURABLE FIT','Only one restrictive arrangement works, or major geometric alteration is required.','Several arrangements work, but flexibility compromises circulation or resource access.','Multiple configurations remain usable, connected, and legible with minimal alteration.'],
      ['WP-05','SECTION + ENVIRONMENT','Uniform extrusion with little environmental reach or sectional differentiation.','Several regions could vary in height or environmental condition, but lack a larger relationship.','Interconnected levels, voids, changing heights, and controlled gradients support different work modes.']
    ]
  },
  GATHERING:{
    title:'GATHERING / 2D CANDIDATE CRITERIA',
    note:'SCORES DESCRIBE GATHERING-GENERATING POTENTIAL, NOT A FINISHED OCCUPANCY PLAN.',
    criteria:[
      ['GP-01','COLLECTIVE LEGIBILITY','Regions are arbitrary, isolated, or unrelated; no collective organization is legible.','A collective relationship is plausible, but some regions remain ambiguous or weakly connected.','Distinct primary, secondary, and sectional regions clearly form one collective system.'],
      ['GP-02','PARTICIPATION GRADIENT','Only full participation or complete separation is possible.','Several participation positions exist, but their sequence or degree of choice is limited.','A connected gradient supports approach, observation, peripheral and active participation, and withdrawal.'],
      ['GP-03','MULTI-SCALE COLLECTIVE ADAPTABILITY','Only one group size or fixed arrangement works; alternatives lose collective identity.','Several arrangements are plausible, but some group sizes or relationships remain weak.','Large groups, subgroups, low occupancy, and informal use remain coherent with limited alteration.'],
      ['GP-04','INTERACTION GEOMETRY POTENTIAL','Participants lack useful orientation, proximity, visual relationships, or approach connections.','Several interaction relationships exist, but only for particular regions or with major added organization.','Multiple positions support coordinated ways to see, approach, orient toward, and engage activity.'],
      ['GP-05','MOVEMENT + GATHERING','Movement fragments gathering, crosses focal relationships, or is blocked by occupation.','Gathering and movement can coexist, but conflicts and disrupted regions remain.','Movement approaches, connects, and activates gathering while preserving coherent collective zones.']
    ]
  },
  INTERSTITIAL:{
    title:'INTERSTITIAL SPACE / CRITERIA',
    note:'SCORES DESCRIBE RELATIONAL PERFORMANCE BETWEEN PROGRAMS, NOT AN ISOLATED LEFTOVER SHAPE.',
    criteria:[
      ['IS-01','CROSS-PROGRAM MEDIATION','Residual or inappropriate program relationships; required relationships are isolated or confused.','Several important relationships are mediated, but some programs are isolated, overconnected, or weakly differentiated.','Required connections and separations form one legible building system.'],
      ['IS-02','MULTIMODAL CONNECTIVITY','Connections are missing, indirect, contradictory, or visually implied without needed access.','Destinations are partially connected, but route hierarchy or sectional comprehension remains incomplete.','Physical, perceptual, and sectional systems form a coordinated, direct, understandable network.'],
      ['IS-03','MOVEMENT + OCCUPATION','Only passage or residual area; occupation repeatedly obstructs movement.','Several occupiable conditions exist, but movement and occupation conflict or remain weakly related.','Circulation, pause, observation, exchange, and overflow reinforce one another without compromising movement.'],
      ['IS-04','INTERFACE CALIBRATION','Uniform or contradictory boundaries produce exposure, isolation, confusion, or abrupt transitions.','Several interface types exist, but the gradient is incomplete, inconsistent, or weakly coordinated.','Differentiated interfaces create appropriate, legible gradients of access, visibility, enclosure, privacy, and environmental exchange.'],
      ['IS-05','SECTIONAL CO-PRESENCE','Void or atrium is isolated, reaches few programs or levels, or creates uncontrolled conflict.','Several regions receive influence, but distribution is limited, uneven, or insufficiently regulated.','Environmental and perceptual influence reaches intended programs and levels while declining or filtering appropriately.']
    ]
  }
};
const fallbackTypeTemplate=type=>({title:`${type} / CRITERIA`,note:'TYPE-SPECIFIC CRITERIA WILL BE ADDED TO THIS TEMPLATE.',criteria:evaluationCriteria.map(label=>[label,label,'Limited evidence.','Plausible potential.','Strong potential.'])});
